import React from "react";

export default function Profile() {

const user = JSON.parse(
localStorage.getItem("user")
);

return (

<div style={{

minHeight:"100vh",

background:"#f1f5f9",

display:"flex",

justifyContent:"center",

alignItems:"center"

}}>

<div style={{

width:"500px",

background:"white",

borderRadius:"20px",

padding:"35px",

boxShadow:"0 10px 30px rgba(0,0,0,0.15)"

}}>

<div style={{textAlign:"center"}}>

<img

src="https://cdn-icons-png.flaticon.com/512/3135/3135715.png"

alt="profile"

style={{

width:"100px",

height:"100px",

borderRadius:"50%",

marginBottom:"15px"

}}

/>

<h1>

{user?.name}

</h1>

<p style={{color:"gray"}}>

{user?.role}

</p>

</div>

<hr />

<div style={{marginTop:"25px"}}>

<h3>📧 Email</h3>

<p>

{user?.email}

</p>

</div>

<div style={{marginTop:"20px"}}>

<h3>🎓 Role</h3>

<p>

{user?.role}

</p>

</div>

<div style={{marginTop:"20px"}}>

<h3>🔒 Password</h3>

<p>

Hidden for Security

</p>

</div>

<button

onClick={()=>{

localStorage.removeItem("user");

window.location.href="/login";

}}

style={{

marginTop:"30px",

width:"100%",

padding:"12px",

background:"#ef4444",

color:"white",

border:"none",

borderRadius:"10px",

cursor:"pointer",

fontSize:"16px"

}}

>

Logout

</button>

</div>

</div>

)

}
